mapper.select:
SELECT np.id, np.project_name, np.project_category, np.description, np.standard_duration, np.caregiver_id, np.frequency, np.status, np.created_at, np.updated_at, u.real_name as caregiver_name FROM nursing_projects np LEFT JOIN users u ON np.caregiver_id = u.id
AND ( np.project_name LIKE CONCAT('%', #{searchKeyword}, '%') OR np.project_category LIKE CONCAT('%', #{searchKeyword}, '%') OR np.description LIKE CONCAT('%', #{searchKeyword}, '%') OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%') )
AND np.project_category = #{projectCategory}
AND np.status = #{status}
AND np.caregiver_id = #{caregiverId}
ORDER BY np.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM nursing_projects np
LEFT JOIN users u ON np.caregiver_id = u.id


        AND (
        np.project_name LIKE CONCAT('%', #{searchKeyword}, '%')
        OR np.project_category LIKE CONCAT('%', #{searchKeyword}, '%')
        OR np.description LIKE CONCAT('%', #{searchKeyword}, '%')
        OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%')
        )


        AND np.project_category = #{projectCategory}


        AND np.status = #{status}


        AND np.caregiver_id = #{caregiverId}

